import { useState } from 'react';
import { BaseNode, FieldText, FieldSelect } from './BaseNode';
import { LogIn } from 'lucide-react';

export const InputNode = ({ id, data }) => {
  const [currName,  setCurrName]  = useState(data?.inputName  || id.replace('customInput-', 'input_'));
  const [inputType, setInputType] = useState(data?.inputType  || 'Text');

  return (
    <BaseNode id={id} title="Input" accentColor="#6366f1" Icon={LogIn}
      outputs={[{ id: 'value', label: 'value' }]}>
      <FieldText   label="Name" value={currName}  onChange={e => setCurrName(e.target.value)}  placeholder="input_name" />
      <FieldSelect label="Type" value={inputType} onChange={e => setInputType(e.target.value)}
        options={[{ value: 'Text', label: 'Text' }, { value: 'File', label: 'File' }]} />
    </BaseNode>
  );
};
